<?php
declare(strict_types=1); namespace App\Services\Finance;
use App\Models\{Classroom,Student}; use App\Models\Finance\{FeeType,StudentInvoice,StudentInvoiceItem}; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class MonthlySppService { public function preview(Classroom $classroom,int $yearId,string $month):array{return $classroom->students()->where('students.status','active')->get()->map(fn(Student $s)=>['student'=>$s,'exists'=>StudentInvoice::where('student_id',$s->id)->where('academic_year_id',$yearId)->whereDate('billing_month',$month.'-01')->exists()])->all();} public function generate(Classroom $classroom,int $yearId,string $month,int|string $amount,?int $userId=null):int{return DB::transaction(function()use($classroom,$yearId,$month,$amount,$userId){$fee=FeeType::firstOrCreate(['code'=>'SPP'],['name'=>'SPP']);$count=0;foreach($this->preview($classroom,$yearId,$month) as $row){if($row['exists'])continue;$invoice=StudentInvoice::create(['student_id'=>$row['student']->id,'academic_year_id'=>$yearId,'invoice_number'=>'SPP-'.str_replace('-','',$month).'-'.Str::upper(Str::random(8)),'billing_month'=>$month.'-01','issue_date'=>now(),'due_date'=>$month.'-10','subtotal'=>$amount,'total'=>$amount,'outstanding_amount'=>$amount,'status'=>'open','created_by'=>$userId]);StudentInvoiceItem::create(['invoice_id'=>$invoice->id,'fee_type_id'=>$fee->id,'description'=>'SPP '.$month,'qty'=>1,'unit_amount'=>$amount,'amount'=>$amount]);$count++;}return $count;});} }
